import{f as r,c as a,o as t,a5 as n}from"./chunks/framework.BsEAYNxL.js";const d=JSON.parse('{"title":"AI 编年史 06：对齐 (Alignment) 的驯化之路","description":"","frontmatter":{"title":"AI 编年史 06：对齐 (Alignment) 的驯化之路","date":"2026-02-14T00:00:00.000Z","categories":["AI","Tech History"],"tags":["Alignment","RLHF","DPO","PPO","InstructGPT","Chronicle"],"ai_role":"writer","reading_stats":{"count":815,"minutes":3}},"headers":[],"relativePath":"ai-chronicles/07-alignment.md","filePath":"ai-chronicles/07-alignment.md","lastUpdated":null}'),i={name:"ai-chronicles/07-alignment.md"};function o(l,e,s,h,u,g){return t(),a("div",null,[...e[0]||(e[0]=[n('<h2 id="_0-核心工程直觉-幻觉是-feature-不是-bug" tabindex="-1">0. 核心工程直觉：幻觉是 Feature，不是 Bug <a class="header-anchor" href="#_0-核心工程直觉-幻觉是-feature-不是-bug" aria-label="Permalink to &quot;0. 核心工程直觉：幻觉是 Feature，不是 Bug&quot;">​</a></h2><p>LLM 的本质是在做 <strong>条件概率的下一步预测</strong>。</p><ul><li><strong>幻觉 (Hallucination)</strong>：更像“在不知道的时候依然要给出一个听起来合理的续写”。所以你要把它当成一个默认会胡说的系统，再通过机制把胡说压下去。</li><li><strong>对齐 (Alignment)</strong>：就是通过 SFT 和 RLHF 等手段，强行扭转它的概率分布，让它“不说谎”或“承认自己不知道”。</li></ul><h2 id="第一阶段-pre-train-fine-tune-——-鹦鹉学舌-2018-2021" tabindex="-1">第一阶段：Pre-train + Fine-tune —— 鹦鹉学舌 (2018 - 2021) <a class="header-anchor" href="#第一阶段-pre-train-fine-tune-——-鹦鹉学舌-2018-2021" aria-label="Permalink to &quot;第一阶段：Pre-train + Fine-tune —— 鹦鹉学舌 (2018 - 2021)&quot;">​</a></h2><p>在 GPT-3 时代，模型虽然什么都懂，但它只是一个“续写机器”。</p><ul><li><strong>Prompt</strong>: &quot;帮我写首诗。&quot;</li><li><strong>Completion</strong>: &quot;写首诗 / 啊，美丽的太阳...&quot; (它以为你在做文本接龙)</li></ul><h3 id="_1-1-痛点" tabindex="-1">1.1 痛点 <a class="header-anchor" href="#_1-1-痛点" aria-label="Permalink to &quot;1.1 痛点&quot;">​</a></h3><p>模型没有“指令遵循” (Instruction Following) 的概念。它不知道你想让它干什么，它只想预测下一个词。</p><h3 id="_1-2-解决方案-sft-supervised-fine-tuning" tabindex="-1">1.2 解决方案：SFT (Supervised Fine-Tuning) <a class="header-anchor" href="#_1-2-解决方案-sft-supervised-fine-tuning" aria-label="Permalink to &quot;1.2 解决方案：SFT (Supervised Fine-Tuning)&quot;">​</a></h3><ul><li>人工写好 {指令, 回答} 的数据对。</li><li>让模型在这些高质量数据上微调。</li><li><strong>结果</strong>：模型学会了“听话”。</li><li><strong>代表作</strong>：<strong><a href="https://arxiv.org/abs/2109.01652" target="_blank" rel="noreferrer">Google FLAN (2021)</a></strong>。</li></ul><h2 id="第二阶段-rlhf-——-人类反馈强化学习-2022" tabindex="-1">第二阶段：RLHF —— 人类反馈强化学习 (2022) <a class="header-anchor" href="#第二阶段-rlhf-——-人类反馈强化学习-2022" aria-label="Permalink to &quot;第二阶段：RLHF —— 人类反馈强化学习 (2022)&quot;">​</a></h2><p>ChatGPT 的杀手锏。</p><h3 id="_2-1-痛点" tabindex="-1">2.1 痛点 <a class="header-anchor" href="#_2-1-痛点" aria-label="Permalink to &quot;2.1 痛点&quot;">​</a></h3><p>SFT 数据太贵了。而且对于“写一个好笑的笑话”这种任务，人类很难写出完美的标准答案，但人类很容易<strong>判断</strong>哪个笑话更好笑。</p><h3 id="_2-2-核心思想-rlhf-reinforcement-learning-from-human-feedback" tabindex="-1">2.2 核心思想：RLHF (Reinforcement Learning from Human Feedback) <a class="header-anchor" href="#_2-2-核心思想-rlhf-reinforcement-learning-from-human-feedback" aria-label="Permalink to &quot;2.2 核心思想：RLHF (Reinforcement Learning from Human Feedback)&quot;">​</a></h3><ol><li><strong>SFT</strong>：先微调一个还不错的模型。</li><li><strong>Reward Model (RM)</strong>： <ul><li>让模型生成几个不同的回答 (A, B, C, D)。</li><li>让人类排序 (A &gt; C &gt; D &gt; B)。</li><li>训练一个 RM 模型，去模仿人类的打分偏好。</li></ul></li><li><strong><a href="https://arxiv.org/abs/1707.06347" target="_blank" rel="noreferrer">PPO (Proximal Policy Optimization)</a></strong>： <ul><li>用 RM 给模型的生成结果打分。</li><li>用强化学习算法 (PPO) 更新模型参数，让它生成的回答分数更高。</li></ul></li></ol><h3 id="_2-3-意义" tabindex="-1">2.3 意义 <a class="header-anchor" href="#_2-3-意义" aria-label="Permalink to &quot;2.3 意义&quot;">​</a></h3><p><strong><a href="https://arxiv.org/abs/2203.02155" target="_blank" rel="noreferrer">InstructGPT (ChatGPT 的前身, 2022)</a></strong> 证明了：1.3B 参数的 RLHF 模型，效果胜过 175B 的 GPT-3。这是<strong>以小博大</strong>的胜利。</p><h2 id="第三阶段-dpo-——-告别强化学习-2023-2024" tabindex="-1">第三阶段：DPO —— 告别强化学习 (2023 - 2024) <a class="header-anchor" href="#第三阶段-dpo-——-告别强化学习-2023-2024" aria-label="Permalink to &quot;第三阶段：DPO —— 告别强化学习 (2023 - 2024)&quot;">​</a></h2><p>RLHF 很强，但太难训练了。PPO 算法极其不稳定，超参数极其敏感。</p><h3 id="_3-1-核心思想-dpo-direct-preference-optimization" tabindex="-1">3.1 核心思想：DPO (Direct Preference Optimization) <a class="header-anchor" href="#_3-1-核心思想-dpo-direct-preference-optimization" aria-label="Permalink to &quot;3.1 核心思想：DPO (Direct Preference Optimization)&quot;">​</a></h3><ul><li><strong>斯坦福论文</strong>：<strong><a href="https://arxiv.org/abs/2305.18290" target="_blank" rel="noreferrer"><em>Direct Preference Optimization: Your Language Model is Secretly a Reward Model</em> (2023)</a></strong></li><li><strong>原理</strong>：直接在偏好数据对 (Winner, Loser) 上优化模型，不需要单独训练 Reward Model，也不需要 PPO。</li><li><strong>公式</strong>：从数学上证明了 DPO 等价于 RLHF。</li><li><strong>优势</strong>：训练极其简单，就像微调一样稳定，显存占用更低。</li></ul><h3 id="_3-2-现状" tabindex="-1">3.2 现状 <a class="header-anchor" href="#_3-2-现状" aria-label="Permalink to &quot;3.2 现状&quot;">​</a></h3><p>DPO 及其变体 (<strong><a href="https://arxiv.org/abs/2310.12036" target="_blank" rel="noreferrer">IPO</a></strong>, <strong><a href="https://arxiv.org/abs/2402.01306" target="_blank" rel="noreferrer">KTO</a></strong>) 已经成为开源社区微调模型的主流范式。Llama 3, Mistral 等模型都大量使用了 DPO。</p><h2 id="第四阶段-constitutional-ai-——-自我对齐-2024-future" tabindex="-1">第四阶段：Constitutional AI —— 自我对齐 (2024 - Future) <a class="header-anchor" href="#第四阶段-constitutional-ai-——-自我对齐-2024-future" aria-label="Permalink to &quot;第四阶段：Constitutional AI —— 自我对齐 (2024 - Future)&quot;">​</a></h2><p>让人类去标注数据还是太慢了。能不能让 AI 自己管自己？</p><h3 id="_4-1-核心思想" tabindex="-1">4.1 核心思想 <a class="header-anchor" href="#_4-1-核心思想" aria-label="Permalink to &quot;4.1 核心思想&quot;">​</a></h3><ul><li><strong><a href="https://www.anthropic.com/index/constitutional-ai-harmlessness-from-ai-feedback" target="_blank" rel="noreferrer">Anthropic (Claude)</a></strong> 提出 <strong><a href="https://arxiv.org/abs/2212.08073" target="_blank" rel="noreferrer">Constitutional AI (2022)</a></strong>。</li><li>给 AI 一部“宪法” (Constitution)，包含一系列原则（如“不能种族歧视”、“不能教人犯罪”）。</li><li><strong>RLAIF (RL from AI Feedback)</strong>：让 AI 根据宪法给自己生成的回答打分，或者修改不合规的回答。</li><li><strong>结果</strong>：Claude 系列模型以“安全”和“守规矩”著称。</li></ul><h3 id="_4-2-总结" tabindex="-1">4.2 总结 <a class="header-anchor" href="#_4-2-总结" aria-label="Permalink to &quot;4.2 总结&quot;">​</a></h3><p>对齐技术决定了 AI 是人类的助手还是终结者。</p>',30)])])}const f=r(i,[["render",o]]);export{d as __pageData,f as default};
